def transform(g):
    h,w=len(g),len(g[0])
    cnt=Counter(v for r in g for v in r)
    s=min(cnt,key=cnt.get)
    cells=[(i,j) for i in range(h) for j in range(w) if g[i][j]==s]
    rmin=min(i for i,_ in cells); rmax=max(i for i,_ in cells)
    cmin=min(j for _,j in cells); cmax=max(j for _,j in cells)
    out=[r[:] for r in g]
    def fill(i,j):
        if out[i][j]!=s: out[i][j]=2
    # hull perimeter
    for j in range(cmin,cmax+1):
        fill(rmin,j); fill(rmax,j)
    for i in range(rmin,rmax+1):
        fill(i,cmin); fill(i,cmax)
    # interior lines: row/col containing an adjacent shape pair
    for i in range(h):
        row=[j for j in range(w) if g[i][j]==s]
        if any(b-a==1 for a,b in zip(row,row[1:])) and not (i in (rmin,rmax)):
            for j in range(row[0],row[-1]+1): fill(i,j)
